package com.taskmanager.controller;import com.taskmanager.dto.*;import com.taskmanager.enums.*;import com.taskmanager.service.TaskService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import java.util.*;
@RestController @RequestMapping("/api/tasks") public class TaskController{private final TaskService s;public TaskController(TaskService s){this.s=s;}@GetMapping public List<TaskResponse> list(Authentication a,@RequestParam(required=false) TaskStatus status,@RequestParam(required=false) TaskPriority priority,@RequestParam(required=false) String search){return s.list(a.getName(),status,priority,search);}@GetMapping("/stats")public Map<String,Long> stats(Authentication a){return s.stats(a.getName());}@GetMapping("/{id}")public TaskResponse get(Authentication a,@PathVariable Long id){return s.get(a.getName(),id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public TaskResponse create(Authentication a,@Valid @RequestBody TaskRequest r){return s.create(a.getName(),r);}@PutMapping("/{id}")public TaskResponse update(Authentication a,@PathVariable Long id,@Valid @RequestBody TaskRequest r){return s.update(a.getName(),id,r);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(Authentication a,@PathVariable Long id){s.delete(a.getName(),id);}}
